-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_satscores AS SELECT satscores.cds AS cds, satscores.rtype AS rtype, satscores.sname AS sname, satscores.dname AS dname, satscores.cname AS cname, satscores.enroll12 AS enroll12, satscores.NumTstTakr AS NumTstTakr, satscores.AvgScrRead AS AvgScrRead, satscores.AvgScrMath AS AvgScrMath, satscores.AvgScrWrite AS AvgScrWrite, satscores.NumGE1500 AS NumGE1500, cds.NCESDist AS NCESDist, cds.NCESSchool AS NCESSchool, cds.StatusType AS StatusType, cds.County AS County, cds.District AS District, cds.School AS School, cds.Street AS Street, cds.StreetAbr AS StreetAbr, cds.City AS City, cds.Zip AS Zip, cds.State AS State, cds.MailStreet AS MailStreet, cds.MailStrAbr AS MailStrAbr, cds.MailCity AS MailCity, cds.MailZip AS MailZip, cds.MailState AS MailState, cds.Phone AS Phone, cds.Ext AS Ext, cds.Website AS Website, cds.OpenDate AS OpenDate, cds.ClosedDate AS ClosedDate, cds.Charter AS Charter, cds.CharterNum AS CharterNum, cds.FundingType AS FundingType, cds.DOC AS DOC, cds.DOCType AS DOCType, cds.SOC AS SOC, cds.SOCType AS SOCType, cds.EdOpsCode AS EdOpsCode, cds.EdOpsName AS EdOpsName, cds.EILCode AS EILCode, cds.EILName AS EILName, cds.GSoffered AS GSoffered, cds.GSserved AS GSserved, cds.Virtual AS Virtual, cds.Magnet AS Magnet, cds.Latitude AS Latitude, cds.Longitude AS Longitude, cds.AdmFName1 AS AdmFName1, cds.AdmLName1 AS AdmLName1, cds.AdmEmail1 AS AdmEmail1, cds.AdmFName2 AS AdmFName2, cds.AdmLName2 AS AdmLName2, cds.AdmEmail2 AS AdmEmail2, cds.AdmFName3 AS AdmFName3, cds.AdmLName3 AS AdmLName3, cds.AdmEmail3 AS AdmEmail3, cds.LastUpdate AS LastUpdate FROM satscores LEFT JOIN schools AS cds ON satscores.cds = cds.CDSCode;
